begin;
do $$declare a uuid; u uuid:=gen_random_uuid(); s uuid; s2 uuid; t uuid; subj text; p uuid; p2 uuid; denied boolean; credits int;begin
select user_id into a from public.academy_staff where role='admin' limit 1;
perform set_config('request.jwt.claim.sub',a::text,true);
insert into auth.users(id,email,email_confirmed_at) values(u,'tuition-verification@example.invalid',now());
select id,subjects[1] into t,subj from public.teachers limit 1;
insert into public.students(first_name,last_name,father_name,national_id,mobile,email,birth_date,address,teacher_id,subject,weekday,class_time,opening_credit,opening_debt,opening_paid) values('آزمایش','موقت','آزمایش','9999999991','09999999991','tuition-verification@example.invalid','2000-01-01','آزمایش',t,subj,5,'03:00',2,1000000,3000000) returning id into s;
if (select user_id from public.students where id=s) is distinct from u then raise exception 'account linking failed';end if;
insert into public.students(first_name,last_name,father_name,national_id,mobile,birth_date,address,teacher_id,subject,weekday,class_time) values('دیگر','آزمایش','آزمایش','9999999992','09999999992','2000-01-01','آزمایش',t,subj,5,'03:20') returning id into s2;
update public.tuition_bank_account set holder='آزمایش موقت',card='1111111111111111',iban='IR111111111111111111111111';
perform set_config('test.student',s::text,true);perform set_config('test.other_student',s2::text,true);perform set_config('test.admin',a::text,true);perform set_config('test.user',u::text,true);
perform set_config('request.jwt.claim.sub',u::text,true);
insert into public.payments(student_id,purpose,terms,amount,reference,status,submitted_by) values(s,'opening_debt',0,500000,'TEST-TUITION-DEBT-1','pending',u) returning id into p;
if (select sum(amount) from public.payments where student_id=s and status='approved') is not null then raise exception 'pending affected balance';end if;
denied:=false;begin update public.payments set status='approved' where id=p;exception when others then denied:=true;end;if not denied then raise exception 'student self approval allowed';end if;
denied:=false;begin insert into public.payments(student_id,purpose,terms,amount,reference,status) values(s2,'tuition',1,2000000,'TEST-OTHER','pending');exception when others then denied:=true;end;if not denied then raise exception 'cross-student receipt allowed';end if;
perform set_config('request.jwt.claim.sub',a::text,true);
update public.payments set status='approved' where id=p;
if (select opening_debt-(select sum(amount) from public.payments where student_id=s and purpose='opening_debt' and status='approved') from public.students where id=s)<>500000 then raise exception 'partial debt wrong';end if;
denied:=false;begin update public.payments set status='approved' where id=p;exception when others then denied:=true;end;if not denied then raise exception 'repeat approval allowed';end if;
denied:=false;begin insert into public.sessions(student_id,starts_at,status) values(s,now(),'completed');exception when others then denied:=true;end;if not denied then raise exception 'debt attendance allowed';end if;
insert into public.payments(student_id,purpose,terms,amount,reference,status) values(s,'opening_debt',0,500000,'TEST-TUITION-DEBT-2','approved');
insert into public.payments(student_id,purpose,terms,amount,reference,status) values(s,'tuition',1,2000000,'TEST-TUITION-TERM','pending') returning id into p2;
if (select coalesce(sum(terms*4),0) from public.payments where student_id=s and status='approved')<>0 then raise exception 'pending created sessions';end if;
update public.payments set status='approved' where id=p2;
select opening_credit+(select sum(terms*4) from public.payments where student_id=s and status='approved') into credits from public.students where id=s;
if credits<>6 then raise exception 'opening credit doubled';end if;
for i in 1..6 loop insert into public.sessions(student_id,starts_at,status) values(s,now()+i*interval '7 days','completed');end loop;
denied:=false;begin insert into public.sessions(student_id,starts_at,status) values(s,now()+interval '49 days','completed');exception when others then denied:=true;end;if not denied then raise exception 'overspent credit';end if;
if (select sum(teacher_share) from public.sessions where student_id=s)<>1800000 then raise exception 'teacher share wrong';end if;
insert into public.payments(student_id,purpose,terms,amount,reference,status) values(s,'tuition',1,2000000,'TEST-TUITION-REJECT','pending') returning id into p2;
update public.payments set status='rejected',review_note='واریز یافت نشد' where id=p2;
denied:=false;begin delete from public.payments where id=p;exception when others then denied:=true;end;if not denied then raise exception 'ledger delete allowed';end if;
denied:=false;begin insert into public.payments(student_id,purpose,terms,amount,reference,status) values(s,'tuition',1,2000000,'TEST-TUITION-TERM','pending');exception when unique_violation then denied:=true;end;if not denied then raise exception 'duplicate reference allowed';end if;
end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('test.user'),true);
do $$begin
if (select count(*) from public.students)<>1 then raise exception 'student RLS exposed another record';end if;
if exists(select 1 from public.payments where student_id<>current_setting('test.student')::uuid) then raise exception 'payment RLS leaked';end if;
end$$;
reset role;
rollback;
select 'PASS: balances, partial debt, approval, rejection, duplicate receipt, session eligibility, payroll, account linking and student RLS; all test data rolled back' as verification;
